CREATE TABLE IF NOT EXISTS gis_phase366_certification_registry (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), registry_id TEXT NOT NULL UNIQUE, certification_version TEXT NOT NULL, authoritative_source_id TEXT NOT NULL, feature_id TEXT NOT NULL, state_code TEXT, status TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL DEFAULT 0, certification_hash TEXT, chain_hash TEXT, certified_at TIMESTAMPTZ, registered_at TIMESTAMPTZ NOT NULL DEFAULT now(), evidence JSONB NOT NULL DEFAULT '{}'::jsonb, UNIQUE(certification_version,authoritative_source_id,feature_id)); CREATE INDEX IF NOT EXISTS idx_phase366_registry_feature ON gis_phase366_certification_registry(feature_id); CREATE INDEX IF NOT EXISTS idx_phase366_registry_state ON gis_phase366_certification_registry(state_code); CREATE INDEX IF NOT EXISTS idx_phase366_registry_status ON gis_phase366_certification_registry(status);